// AUTO-GENERATED by `npm run build` from src/melon_drive/ — do not edit directly.
import { Instance, CustomCameraMode, PointTemplate, CSInputs, CSMoveType } from 'cs_script/point_script';

// Toggle to false once driving works to quiet the console back down.
const DEBUG = true;
// (The jump/contact debug view is separate — toggled per player from the
// user menu, see physics/jump-debug.js.)

/** @param {string} text */
function Debug(text) {
    if (DEBUG) {
        Instance.Msg(`[melon_drive] ${text}`);
    }
}

// Driving: acceleration, speed cap, friction, and how a melon settles at rest.

// Force ratios ported from the original melonracer GMod gamemode
// (sent_melon_base/init.lua ENT:Think + gamemode/shared.lua DefXSpeed):
// forward is the strongest push, reverse is half that, strafe is weaker
// still — keeping FORWARD_ACCEL as our existing tuned baseline.
const FORWARD_ACCEL = 325; // units/sec^2 while holding forward (was 900, then 500, then 400, then 450 — a heavier, slower build-up: ~2s to MAX_SPEED)
const REVERSE_ACCEL = FORWARD_ACCEL * 0.5; // 0.5x forward, matches original's Reverse/Forward ratio
const STRAFE_ACCEL = FORWARD_ACCEL * 0.4; // 0.4x forward, matches original's Strafe/Forward ratio
const MAX_SPEED = 650; // units/sec, horizontal speed cap
const COAST_FRICTION = 120; // units/sec^2 horizontal slowdown with no input — low, so the melon keeps rolling on its own momentum instead of grinding to a stop

// Below this horizontal AND vertical speed, with no steering/jump input,
// the melon counts as fully settled — UpdateKart stops re-pinning its
// velocity/spin to zero every tick and lets vphysics run it completely
// freely, so its own weight and (irregular) resting shape can tip or slide
// it exactly as real physics dictates instead of gluing it to whatever spot
// it stopped at.
const MELON_REST_SPEED = 2; // units/sec

// The instant a melon crosses into "fully settled" (see MELON_REST_SPEED
// above), vphysics owns its orientation completely — but a perfectly
// balanced landing (e.g. resting dead upright on end) is a knife-edge
// equilibrium that a deterministic physics sim has no numerical noise to
// break on its own, so it would otherwise freeze there forever instead of
// tipping onto a stable side. UpdateKart gives it one small, random-direction
// spin nudge the moment it settles to break that tie; real vphysics then
// decides — from the melon's actual collision shape and whatever surface
// it's resting on — whether that nudge grows into a proper topple or just
// gets damped straight back to rest.
const SETTLE_NUDGE_ANGULAR_SPEED = 40; // deg/sec, one-off pitch/roll kick on settling

// Steering grip: while holding forward on the ground, the melon's horizontal
// velocity is turned towards the look direction by up to STEER_GRIP_RATE
// degrees per second, keeping its speed — so it goes where the camera points
// instead of only being pushed that way by FORWARD_ACCEL (which at MAX_SPEED
// turned it slowly, like a hovercraft). Only for velocity that is at most
// STEER_GRIP_MAX_ANGLE off the look direction: looking back or far to the
// side is braking/turning around via plain acceleration, not a snap U-turn.
// Higher STEER_GRIP_RATE: more direct, less drift. 0 = off (old behavior).
const STEER_GRIP_RATE = 180; // degrees/sec
const STEER_GRIP_MAX_ANGLE = 100; // degrees
// The same grip in the air (jumps, falls, after a wall bounce), at its own
// rate — without it, FORWARD_ACCEL alone barely turned a melon at speed.
// The bounce tick itself is never steered, so the reflected angle is applied
// as computed; lower this if bounces should keep their angle longer. 0 = no
// air steering beyond plain acceleration.
const STEER_AIR_GRIP_RATE = 180; // degrees/sec

// Jumping: ground jump, wall jump, and the ground contact they rely on (see logic/contact.js).

const JUMP_SPEED = 370; // units/sec upward impulse
// The ground jump needs real ground contact (see logic/contact.js), and a
// new one since the last jump — no cooldown: touching down is what resets
// it. (The "new contact" part stops a second press within
// GROUND_COYOTE_TIME of taking off from jumping again.)
//
// Ground contact is measured, not guessed from distance: each tick the
// vertical velocity we commanded is compared with what physics made of it.
// In the air gravity pulls it down by the full GRAVITY; anything holding
// the melon up (the floor, a slope) cancels part of that. So "supported" =
// the vertical acceleration was clearly less than free fall — independent
// of the melon's (non-round) shape, and a melon hovering just above the
// floor is correctly "in the air". A short line trace down then confirms
// what's holding it up is floor-like (GROUND_NORMAL_MIN_Z), not a wall or
// an edge. GROUND_COYOTE_TIME only bridges the tiny hops a rolling,
// egg-shaped melon makes — keep it short.
const GRAVITY = 800; // units/sec^2 — CS2's sv_gravity, what vphysics pulls the melon down with
const FREE_FALL_FRACTION = 0.8; // vertical accel at or below -FREE_FALL_FRACTION * GRAVITY counts as falling freely (not supported); lower = stricter
// Units down from the melon's center the floor-confirming trace reaches.
// A resting melon's center sits only ~7 units above the floor (see the
// floor distance in the DEBUG overlay / jump log), so this is its half
// height, rolled onto its long side or on a slope, plus a small margin. It
// used to be 48, which found the floor while the melon was still ~40 units
// up in a jump — together with a moment of measured "support" that allowed
// a jump in mid-air.
const GROUND_CHECK_DISTANCE = 20;
const GROUND_NORMAL_MIN_Z = 0.5; // surface must be at least this floor-like (not a wall) to count as ground
const GROUND_COYOTE_TIME = 0.08; // seconds a ground contact stays valid after losing it — only bridges rolling hops
// Right after a jump (ground or wall) the floor can still be pushing the
// melon up for a tick, which reads exactly like support — so ground contact
// doesn't count for this long after any jump. Otherwise a second press just
// after taking off jumped again in mid-air.
const GROUND_LIFTOFF_TIME = 0.15; // seconds

// Wall jump: in the air, touching a wall (a line trace in any of
// WALL_PROBE_DIRECTIONS horizontal directions finds a steep surface within
// WALL_CONTACT_DISTANCE and physics just stopped the melon's motion into
// it — see WALL_TOUCH_MIN_STOP_SPEED — or a wall impact just happened) and pressing jump
// pushes the melon off that wall and up. Its strength comes from a charge
// (the HUD jump bar): a wall jump is as strong as the charge is full
// (WALL_JUMP_UP_SPEED / WALL_JUMP_PUSH_SPEED at 100%) and uses up
// WALL_JUMP_CHARGE_COST of it, so chained wall jumps get weaker and weaker;
// the charge refills over WALL_JUMP_RECHARGE_SECONDS. A wall jump never
// raises the melon's speed cap, so chaining them can't build up speed.
// Can't climb one wall forever: after a wall jump, the next one
// needs ground contact first or a different wall (normal differing by more
// than WALL_JUMP_SAME_WALL_DOT) — bouncing between two facing walls chains.
const WALL_PROBE_DIRECTIONS = 8;
const WALL_JUMP_WINDOW = 0.2; // seconds a wall contact stays jumpable — the melon usually bounces off the wall the moment it hits it
const WALL_JUMP_COOLDOWN = 0.45; // seconds between two wall jumps (was 0.3)
const WALL_JUMP_CHARGE_COST = 0.5; // share of a full charge one wall jump uses — 2 in a row, the second at half strength (was 0.34, ~3 in a row)
const WALL_JUMP_MIN_CHARGE = 0.15; // below this there's no wall jump at all (was 0.1)
const WALL_JUMP_RECHARGE_SECONDS = 5; // empty -> full (was 3)
const WALL_JUMP_UP_SPEED = 240; // units/sec upward — well below the ground jump's JUMP_SPEED (was 380)
const WALL_JUMP_PUSH_SPEED = 160; // units/sec at least away from the wall (more if already moving away faster) (was 250)
const WALL_JUMP_SAME_WALL_DOT = 0.7; // normals closer than this (dot product, ~45°) count as the same wall

// Melon health and impact damage from landings/crashes (wall hits have their own rules in wall-bounce.js).

// Impact damage: every tick we compare the velocity we commanded last tick
// against the melon's actual velocity now. A big gap means physics forcibly
// overrode our command — a wall crash or a hard landing — since gravity and
// our own steering only ever change velocity gradually. That gap's
// magnitude is the "impact speed" damage is based on:
//   damage = (impactSpeed - IMPACT_DAMAGE_THRESHOLD) * IMPACT_DAMAGE_SCALE
// e.g. a 700 u/s impact = (700 - 450) * 0.2 = 50 of MELON_MAX_HEALTH's 70.
// Landing flat on level ground: times FLAT_LANDING_DAMAGE_MULTIPLIER (below).

// The melon's health pool (kart.health), refilled on every respawn at a
// checkpoint (after a break or via the user menu). Shared by landing/crash damage here and wall-hit damage
// (WALL_IMPACT_DAMAGE_* / WALL_BOUNCE_DAMAGE_PER_SPEED in wall-bounce.js).
// The HUD bar shows it as a fraction, so changing it doesn't change the bar.
// Higher: more or harder hits before the melon breaks — more forgiving,
//   crashes matter less, wall bounces that cost health can be chained longer.
// Lower: fewer hits until it breaks — punishing; at or below one typical
//   hard landing's damage (~50 above), a single bad jump breaks it.
const MELON_MAX_HEALTH = 70; // was 80 — every hit now takes ~14% more of the pool
// The melon entity's *engine* health (not kart.health above) — set this high
// on every spawn so the engine's own physics damage never destroys the prop,
// regardless of its Hammer health/damage settings. See MakeUnbreakableByEngine.
// Not a gameplay knob: only has to stay far above anything the engine's
// physics damage could deal.
// Higher: no effect.
// Lower: the engine may destroy the melon prop itself on a hard hit, outside
//   our break/respawn logic — the kart loses its melon instead of breaking
//   and respawning properly.
const MELON_ENGINE_HEALTH = 1000000;
// units/sec of sudden velocity change before it starts to hurt — also the
// gate for whether a landing/crash deals damage at all.
// Higher: more impacts are free — normal jumps and small bumps never hurt,
//   only really hard falls/crashes do; every damaging hit also deals less
//   (the threshold is subtracted first).
// Lower: even ordinary landings and light bumps cost health; set too low,
//   physics noise from rolling over uneven ground chips health away.
const IMPACT_DAMAGE_THRESHOLD = 450;
// health lost per unit/sec beyond the threshold — how steeply damage grows
// once an impact is over it.
// Higher: impacts just above the threshold already hurt a lot; hard crashes
//   break the melon in one hit.
// Lower: damage grows slowly — even big crashes only nibble at health,
//   breaking needs many hard hits.
const IMPACT_DAMAGE_SCALE = 0.2;
// Landing flat on level ground hurts more than the same impact anywhere else
// (a slope lets the melon roll the fall off; a wall crash has its own
// rules): the damage above is multiplied by FLAT_LANDING_DAMAGE_MULTIPLIER
// when the floor under the melon is at least FLAT_LANDING_MIN_NORMAL_Z level
// and the impact came mostly from above (upward share of the impact at least
// FLAT_LANDING_MIN_VERTICAL_SHARE). The threshold itself is unchanged, so
// landings that were free stay free.
// Higher multiplier: big drops onto flat floors break the melon much sooner.
// Lower (1 = off): flat landings hurt the same as any other impact.
const FLAT_LANDING_DAMAGE_MULTIPLIER = 2; // was 1.5
// Floor normal z from which ground counts as flat (1 = perfectly level;
// 0.97 ≈ up to 14° of slope).
// Higher: only really level floors count, gentle ramps don't.
// Lower: moderate slopes count as flat too.
const FLAT_LANDING_MIN_NORMAL_Z = 0.97;
// How much of the impact must point straight up (the floor stopping a fall)
// for it to be a landing rather than a crash that happens to be on flat ground.
// Higher: only near-vertical drops count; fast landings with a lot of forward
// speed lost in the same tick don't.
// Lower: more mixed impacts count as flat landings.
const FLAT_LANDING_MIN_VERTICAL_SHARE = 0.7;

// Heal zones (HEAL_ZONE_*): heal/constants.js, re-exported by index.js.

// Heal zones: a trigger_multiple (filtered to prop_physics like the other
// triggers) with OnStartTouch -> RunScriptInput "heal_enter" and OnEndTouch
// -> RunScriptInput "heal_leave" heals the melon over time while it's
// inside. Health per second, used for a zone whose name doesn't set its own
// rate (see HEAL_ZONE_NAME_PATTERN / HEAL_ZONE_FULL_NAME).
// Higher: a quick stop in the zone refills the melon — heal zones become
//   pit stops you barely slow down for.
// Lower: healing takes a long stay; driving through only helps a little.
const HEAL_ZONE_RATE = 10;
// Optional per-zone rate: a heal trigger named "heal_zone_<rate>" (e.g.
// "heal_zone_25") heals <rate> health per second instead of HEAL_ZONE_RATE.
// Any other name uses HEAL_ZONE_RATE. Overlapping zones don't stack — the
// fastest one counts.
const HEAL_ZONE_NAME_PATTERN = /^heal_zone_(\d+(?:\.\d+)?)$/;
// Full-heal zone: a heal trigger with exactly this name (same heal_enter /
// heal_leave wiring) refills the melon to MELON_MAX_HEALTH on the first tick
// inside and keeps it full while it stays there. Its rate is
// HEAL_ZONE_FULL_RATE, so it always beats any other zone it overlaps.
const HEAL_ZONE_FULL_NAME = "heal_zone_full";
// Not a tuning knob: "infinitely fast" — HealedHealth jumps straight to full.
const HEAL_ZONE_FULL_RATE = Infinity;
// point_template placed in Hammer holding the heal effect's
// info_particle_system: a fresh copy is played at the melon, riding along
// on it, every time it enters a heal zone (any kind). Must match the name
// in Hammer; test/map-templates.test.mjs checks it's there.
const HEAL_PARTICLE_TEMPLATE_NAME = "particle_health_template";
// Seconds a spawned heal effect is kept before it's removed. Removing the
// info_particle_system ends its particles, so this is an upper bound.
// Higher: the effect is never cut short, but copies pile up while melons
//   keep driving in and out of heal zones.
// Lower: cleaned up sooner; below the .vpcf's own duration it's cut off
//   mid-play.
const HEAL_PARTICLE_LIFETIME = 2;

// Wall bounce: contact rules, speed-for-health trade, ratings, bounce HUD and the PERFECT spark.

// Wall bounce: an impact against a wall (any world/brush surface whose
// normal is mostly horizontal — see WALL_NORMAL_MAX_Z) reflects the melon's
// pre-impact velocity off that wall instead of letting vphysics just stop
// it, and can come out *faster* than it went in — trading health for speed.
// How much faster is skill-based: the speed multiplier is fixed per rating
// (BOUNCE_RATINGS[].speedMultiplier), and the rating comes from how close
// the hit was to WALL_BOUNCE_OPTIMAL_ANGLE (measured from the wall's normal,
// 0 = head-on, 90 = grazing) — closeness falls off linearly to 0 at
// WALL_BOUNCE_ANGLE_FALLOFF degrees away from it. A jump timed within
// WALL_BOUNCE_PERFECT_JUMP_WINDOW of the hit (before or after) multiplies the
// result once more — fully for the exact same tick, fading out towards the
// window's edges. Floors/landings never bounce — they keep using the
// plain IMPACT_DAMAGE_* rules (health.js).
const WALL_BOUNCE_MIN_IMPACT = 200; // units/sec of sudden velocity change before a wall hit counts as a bounce at all
const WALL_NORMAL_MAX_Z = 0.5; // |normal.z| above this is a floor/ceiling/steep ramp, not a wall
const WALL_BOUNCE_TRACE_DISTANCE = 160; // ray length from last tick's position along the incoming direction — must reach the wall even at grazing angles (grows with 1/cos(angle))
// A wall the traces find only counts if the melon is actually touching it
// (see IsWallContact in logic/wall-bounce.js) — the trace reaches far ahead,
// so in a small room it finds *some* wall on almost every hard landing or
// bump, which used to bounce the melon off a wall it never touched.
const WALL_CONTACT_DISTANCE = 56; // max units from the melon's center to the wall plane — melon radius plus margin for the tick physics already pushed it back
// A wall the probes find only counts as touched for a wall jump if physics
// actually stopped the melon against it, measured like ground contact: of
// the speed into the wall we commanded last tick, at least
// WALL_CONTACT_MIN_STOP must be gone now — and at least this much in
// absolute terms. Without the absolute part, flying almost parallel past a
// nearby wall (only a few units/sec into it) counted as touching it from
// small physics noise alone.
// (WALL_CONTACT_DISTANCE alone is from the melon's center and let a melon
// still flying towards a wall jump off it before touching it.)
const WALL_TOUCH_MIN_STOP_SPEED = 60; // units/sec of speed into the wall that must have been stopped
const WALL_CONTACT_MIN_STOP = 0.5; // fraction of the into-the-wall speed the impact must have taken away — a landing or friction leaves it almost untouched, a real wall stops it
const WALL_BOUNCE_TRACE_RADIUS = 8; // backup sphere sweep from the current position, for posts/edges the ray slips past
const WALL_BOUNCE_SPHERE_TRACE_DISTANCE = 48;
const WALL_BOUNCE_OPTIMAL_ANGLE = 45; // degrees from the wall normal where the bounce is strongest
const WALL_BOUNCE_ANGLE_FALLOFF = 45; // degrees away from optimal at which the bonus has faded out completely
const WALL_BOUNCE_PERFECT_JUMP_WINDOW = 0.12; // seconds, before or after the hit
const WALL_BOUNCE_PERFECT_JUMP_MULTIPLIER = 1.3; // extra multiplier on top for a perfectly timed jump (scaled down the further off it is)
// The timing press is the jump button, but separate from the normal jump:
// it counts even in the air or while the jump is on cooldown (it gives no
// upward push, only timing credit). Pressing again within this many seconds
// of the previous press is treated as mashing and locks timing credit for
// that long — see RegisterWallTimingPress.
const WALL_TIMING_SPAM_LOCKOUT = 0.4; // seconds
// Every bounce also lifts the melon: its vertical speed is set to at least
// this much upward (a falling melon's fall is cancelled first, one already
// rising keeps its upward speed plus this). Same for every rating.
// Higher: bounces send it up in an arc; 0 = vertical left to physics (old).
// Stronger inside lift zones — see constants/lift.js.
const WALL_BOUNCE_UP_SPEED = 220; // units/sec upward
const WALL_BOUNCE_COOLDOWN = 0.2; // seconds — stops one wall contact from bouncing (and damaging) on consecutive ticks
// Wall hits get their own damage rules, separate from landings: a base part
// from the impact itself (same shape as IMPACT_DAMAGE_*), plus a cost for
// every unit/sec of speed the bounce *gained* — that second part is the
// actual "speed for health" trade. That total is then reduced by how close
// to the optimal angle it hit (the angle factor, 0..1) — jump timing only
// affects speed, not damage. Anything rated PERFECT (BOUNCE_RATINGS[0]) costs
// no health at all; one with no angle bonus pays full price. Charged once the jump window has
// closed (a late jump can still add speed), not on impact itself.
const WALL_IMPACT_DAMAGE_THRESHOLD = 200; // units/sec — same as WALL_BOUNCE_MIN_IMPACT, so any bounce that isn't PERFECT costs health from its first unit/sec
const WALL_IMPACT_DAMAGE_SCALE = 0.3; // health lost per unit/sec beyond the threshold (before the angle reduction)
const WALL_BOUNCE_DAMAGE_PER_SPEED = 0.05; // health lost per unit/sec gained by a bounce
// A bounce may lift the melon above MAX_SPEED — deliberately with no upper
// limit, chained bounces stack. The raised cap then decays back towards
// MAX_SPEED at this rate (and never sits above the melon's actual speed, so
// braking and re-accelerating can't reclaim a boost already lost).
const BOOST_DECAY = 150; // units/sec^2
// The speedometer flashes (PerfectBounce class) for this long after a bounce
// with at least this angle factor — i.e. one that cost little or no health.
const PERFECT_BOUNCE_FLASH_SECONDS = 0.4;
const PERFECT_BOUNCE_ANGLE_FACTOR = 0.8;
// point_template placed in Hammer holding the spark's info_particle_system:
// spawned at the melon on every wall bounce the HUD rates PERFECT
// (BOUNCE_RATINGS[0]) — two fresh copies per hit, one left at the wall and
// one parented to the melon so its player sees it too, and perfect hits by
// several karts at once each get their own. Must match the name in Hammer.
const PERFECT_SPARK_TEMPLATE_NAME = "perfect_hit_particle_template";
// Seconds a spawned spark is kept before it's removed. Removing the
// info_particle_system ends its particles, so this is an upper bound.
// Higher: the effect is never cut short, but more entities pile up when
//   perfect hits come in fast succession.
// Lower: cleaned up sooner; below the .vpcf's own duration the spark is
//   cut off mid-play.
const PERFECT_SPARK_LIFETIME = 2;
// Bounce feedback panel (bounce_panel in speedometer.xml, see
// UpdateBounceHud): shown for this long after each wall bounce.
const BOUNCE_HUD_SECONDS = 1.5;
// Angle scale: 0°..90° split into this many equal segments
// ("bounce_angle_seg_0".."_{N-1}"), 10° each — the one containing 45° is
// styled as the target in speedometer.css, the one actually hit gets "Hit".
const BOUNCE_ANGLE_SEGMENTS = 9;
// Jump-timing bar ("bounce_jump_seg_0".."_{N-1}"), filled by how well the
// jump was timed (1 = same tick as the hit).
const BOUNCE_JUMP_SEGMENTS = 5;
// Rating word by how close to WALL_BOUNCE_OPTIMAL_ANGLE the hit was
// (angleFactor, 1 = exact). First match wins — keep sorted high to low,
// last entry is the catch-all. speedMultiplier is what a bounce with that
// rating does to the melon's speed (before jump timing). cssClass colors the panel; color is the same
// accent for the in-world prediction line (see prediction.js) — keep the two
// in sync with speedometer.css's .Rating* rules.
// PERFECT counts within this many degrees either side of
// WALL_BOUNCE_OPTIMAL_ANGLE (was 4.5°, i.e. minAngleFactor 0.9).
const PERFECT_BOUNCE_TOLERANCE = 6.5; // degrees
const BOUNCE_RATINGS = [
    { minAngleFactor: 1 - PERFECT_BOUNCE_TOLERANCE / WALL_BOUNCE_ANGLE_FALLOFF, label: "PERFECT", speedMultiplier: 1.35, cssClass: "RatingPerfect", color: { r: 255, g: 224, b: 102, a: 255 } },
    { minAngleFactor: 0.7, label: "GOOD", speedMultiplier: 1.1, cssClass: "RatingGood", color: { r: 102, g: 221, b: 102, a: 255 } },
    { minAngleFactor: 0.4, label: "BAD", speedMultiplier: 0.5, cssClass: "RatingBad", color: { r: 102, g: 170, b: 255, a: 255 } },
    { minAngleFactor: 0, label: "MISS", speedMultiplier: 0.3, cssClass: "RatingMiss", color: { r: 255, g: 102, b: 102, a: 255 } },
];

// Boost trail: a glowing band (particles/melon_racer/boost_trail.vpcf, with
// juice droplets as its child) behind a melon while a wall-bounce boost has
// it faster than MAX_SPEED. Started and stopped by ../boost-trail.js.

// point_template placed in Hammer holding the trail's info_particle_system
// (effect particles/melon_racer/boost_trail.vpcf). A fresh copy is spawned
// on the melon, parented so it rides along, when the boost starts, and
// stopped when it's over. Must match the name in Hammer. Without it there's
// simply no trail.
const BOOST_TRAIL_TEMPLATE_NAME = "particle_boost_trail_template";
// The trail starts once the melon is this many units/sec above MAX_SPEED...
// Higher: only big boosts (PERFECT, chained bounces) leave a trail.
// Lower: even a small GOOD bounce shows it; at ~0 it flickers on every
//   tiny overshoot of MAX_SPEED.
const BOOST_TRAIL_START_MARGIN = 30;
// ...and stops once it's back below MAX_SPEED + this. Lower than the start
// margin so a speed hovering around the threshold doesn't toggle it every
// tick.
const BOOST_TRAIL_STOP_MARGIN = 5;
// Seconds a stopped trail's entities are kept, so the particles already out
// fade out instead of vanishing. Must cover the .vpcf's longest particle
// lifetime (0.75 s for the juice droplets).
const BOOST_TRAIL_FADE_SECONDS = 1;

// Lift zones: triggers where wall bounces and wall jumps are tuned for
// climbing a shaft or a high wall by bouncing between its walls. What
// changes inside one is gathered in WallRules (logic/lift.js); the camera
// zoom there is LIFT_CAMERA_* in camera.js.

// A trigger_multiple (filtered to prop_physics like the other triggers) with
// OnStartTouch -> RunScriptInput "lift_enter" and OnEndTouch -> RunScriptInput
// "lift_leave". While the melon is inside, a wall bounce kicks it up by this
// much instead of WALL_BOUNCE_UP_SPEED. Per zone, the name can set it (see
// LIFT_ZONE_NAME_PATTERN). Overlapping zones: the strongest counts.
// Gravity is 800 u/s², so a kick of v climbs about v² / 1600 units:
// 220 -> ~30, 450 -> ~125, 600 -> ~225 per bounce.
const LIFT_ZONE_UP_SPEED = 450; // units/sec upward
// Optional per-zone kick: a lift trigger named "lift_zone_<speed>" (e.g.
// "lift_zone_600") kicks <speed> units/sec up instead of LIFT_ZONE_UP_SPEED.
const LIFT_ZONE_NAME_PATTERN = /^lift_zone_(\d+(?:\.\d+)?)$/;
// In a lift zone a bounce always leaves the wall with at least this much
// horizontal speed, whatever its rating. Shafts are climbed by bouncing
// almost head-on — a MISS (x0.3) — so the melon used to arrive at the
// opposite wall below WALL_BOUNCE_MIN_IMPACT and the chain died there. The
// speed added this way is free (not counted as speed gained for damage).
// Higher: easier to reach the far wall of wide shafts; lower: more skill.
const LIFT_ZONE_MIN_BOUNCE_SPEED = 450; // units/sec
// Wall jumps in a lift zone cost no charge, are always full strength and
// keep a bounce's higher upward kick. A narrow shaft has the melon at the
// opposite wall sooner than WALL_JUMP_COOLDOWN, so there the cooldown is only
// this (the next wall jump still needs the *other* wall, so one wall can't be
// climbed alone) ...
const LIFT_ZONE_WALL_JUMP_COOLDOWN = 0.1; // seconds
// ... and a jump pressed up to this long *before* touching the next wall is
// remembered and fires the wall jump the moment the melon touches it —
// pressing a little early used to be lost (only presses after the contact
// counted, within WALL_JUMP_WINDOW).
const LIFT_ZONE_JUMP_BUFFER = 0.2; // seconds

// Wall-bounce prediction line (see prediction.js).

// Wall-bounce prediction line, drawn in front of the melon (see
// prediction.js): a dotted line along its current direction of travel up to
// the next wall, then on along the direction it would bounce off in —
// colored by the rating (BOUNCE_RATINGS) that wall hit would get at the
// current angle, so the player can steer until it turns PERFECT before
// reaching the wall. Dots are entities spawned from a point_template named
// PREDICTION_DOT_TEMPLATE_NAME (one small, non-solid prop_dynamic inside it)
// — Instance.DebugLine only works in dev environments, so real players
// would never see a debug-drawn line. Without that template in the map it
// falls back to DebugLine anyway, for testing in tools mode.
// Note: the dots are ordinary networked entities, so every player sees every
// kart's prediction line, not just their own.
// Master switch for the whole map. Each player also turns their own line
// on in the user menu ("GUIDE LINE") — off by default.
const PREDICTION_ENABLED = true;
// "debug": Instance.DebugLine — a clean continuous line, but only visible in
//          dev environments (tools mode), never to real players.
// "dots":  entities from PREDICTION_DOT_TEMPLATE_NAME — visible to everyone.
const PREDICTION_RENDER_MODE = "debug";
const PREDICTION_DOT_TEMPLATE_NAME = "prediction_dot_template";
const PREDICTION_LENGTH = 700; // units ahead to look for the next wall
const PREDICTION_REFLECT_LENGTH = 250; // units the bounced-off part of the line continues
const PREDICTION_DOTS_IN = 12; // dots from the melon to the wall
const PREDICTION_DOTS_OUT = 5; // dots along the bounce direction
const PREDICTION_START_OFFSET = 36; // first dot this far ahead of the melon's center, so it isn't hidden inside the melon
const PREDICTION_MIN_SPEED = 80; // units/sec — below this there's no meaningful direction, line hidden
const PREDICTION_NEUTRAL_COLOR = { r: 255, g: 255, b: 255, a: 160 }; // no wall in range

// Breaking: what happens at the crash site and the respawn delay.

// When a melon breaks it doesn't respawn instantly — it shreds apart at the
// crash site (hidden immediately, with the break particle standing in for
// the melon itself) for BREAK_RESPAWN_DELAY seconds before reappearing at the
// last checkpoint. Gives the player a beat to register that it broke instead
// of it just snapping to the checkpoint. Seconds.
// Higher: a break costs more race time and the player watches the burst
//   longer — harsher penalty, can feel like waiting.
// Lower: quicker back on track, a milder penalty; too low and the burst and
//   camera pull-back (BREAK_CAMERA_ZOOM_SECONDS) are cut off before they're
//   seen — it just snaps to the checkpoint.
const BREAK_RESPAWN_DELAY = 3;
// While broken, the chase camera pulls back from the crash site so the
// player actually sees the melon burst (see BreakCameraOffset in
// logic/break-sequence.js): it eases out by this much extra distance/height
// over BREAK_CAMERA_ZOOM_SECONDS, holds there, and snaps back to the
// player's normal offset when the melon respawns BREAK_RESPAWN_DELAY later.
// Seconds the pull-back takes.
// Higher: slower, smoother zoom-out; at or above BREAK_RESPAWN_DELAY it never
//   reaches its full distance before the respawn.
// Lower: a faster, more abrupt jerk back; 0 = jumps straight out.
const BREAK_CAMERA_ZOOM_SECONDS = 0.8;
// Units the camera ends up further back than the player's normal distance.
// Higher: wider view of the burst and the flying pieces, the melon looks small.
// Lower: stays close — the burst fills the screen, pieces fly out of view;
//   0 = no pull-back (only BREAK_CAMERA_EXTRA_HEIGHT).
const BREAK_CAMERA_EXTRA_DISTANCE = 260;
// Units the camera ends up higher than the player's normal height.
// Higher: looks down onto the crash site from above, pieces on the ground
//   are easier to see; in low rooms the camera may end up in the ceiling.
// Lower: flatter view from the side; 0 = no rise (only
//   BREAK_CAMERA_EXTRA_DISTANCE).
const BREAK_CAMERA_EXTRA_HEIGHT = 160;
// How long a break's spawned effect entities (both templates below) are
// kept before being removed — long, so the chunks stay lying at the crash
// site. Removing the info_particle_system ends its particles, so this is an
// upper bound: the .vpcf's own particle lifetime can still end them sooner.
// Seconds.
// Higher: pieces stay lying around longer as traces of past crashes — more
//   entities alive at once (still capped by BREAK_EFFECT_MAX_ACTIVE).
// Lower: the crash site is cleaned up sooner; below the particle's own
//   lifetime it also cuts the burst itself short.
const BREAK_EFFECT_LIFETIME = 180;
// Cap on how many breaks' effects exist at once, so a long session doesn't
// pile up entities — the oldest break's effects go first.
// Higher: more crash sites stay visible with many players/breaks — more
//   entities and physics pieces, costs performance and entity slots.
// Lower: fewer entities; with many breaks old pieces vanish long before
//   BREAK_EFFECT_LIFETIME, possibly while someone's still looking at them.
const BREAK_EFFECT_MAX_ACTIVE = 24;
// Fallback look while broken when no break particle actually spawned (see
// SpawnBreakParticles/BreakMelon) — a dark, dead-looking husk visibly marking
// the crash site instead of the melon just vanishing for BREAK_RESPAWN_DELAY
// seconds with nothing to look at. Only used when the break templates are
// missing or spawn nothing.
// Brighter (r/g/b up): the husk looks less "dead", closer to a normal melon.
// Darker (r/g/b down): more clearly broken; a < 255 makes it see-through,
//   0 hides it completely (the melon just vanishes).
const BREAK_TINT_FALLBACK = { r: 40, g: 40, b: 40, a: 255 };
// Name of a point_template placed in Hammer holding the break effect (e.g. an
// info_particle_system with "Start Active" set so it plays as soon as it's
// spawned, no input needed) — same ForceSpawn-from-a-template convention as
// MELON_TEMPLATE_NAME. Not a tuning value: must match the entity's name in
// Hammer (renaming means renaming it there too, and in MAPPING_API.md).
const BREAK_PARTICLE_TEMPLATE_NAME = "melon_break_template";
// Second, separate break effect layered on top of the one above — e.g. flying
// melon chunks, as opposed to the main burst. Same point_template convention,
// same "must match Hammer" rule.
const BREAK_CHUNKS_PARTICLE_TEMPLATE_NAME = "melon_break_chunks_template";
// Any prop_physics the two break templates above spawn (e.g. the melon
// model's own break pieces, models/cs_italy/italy_food_melon/
// italy_food_melon/piece.vmdl .. piece8.vmdl, added to the chunks template)
// is treated as a break piece: flung outward from the crash site, tinted in
// the melon's color, and left lying there for BREAK_EFFECT_LIFETIME. The
// chunks particle alone is only sprite flecks that fade within moments.
// Units/sec each piece flies outward (along the ground) from the crash site.
// Higher: a more violent burst, pieces scatter wide — they can end up far
//   off, across the track (in karts' way) or out of view.
// Lower: pieces drop in a tight heap where the melon broke; 0 = straight up
//   only (BREAK_PIECE_UP_SPEED).
const BREAK_PIECE_SPEED = 220;
// Units/sec extra upward pop per piece.
// Higher: pieces fly high and stay in the air longer before landing; too
//   high and they hit ceilings indoors.
// Lower: pieces skid along the ground instead of flying; 0 = no pop.
const BREAK_PIECE_UP_SPEED = 180;
// Max degrees/sec of random tumble per axis.
// Higher: pieces spin wildly through the air, a more chaotic burst.
// Lower: pieces fly calmer, keeping their orientation; 0 = no spin at all.
const BREAK_PIECE_SPIN = 600;

